GRANT EXECUTE ON FUNCTION nexus.catalog_tag_set(jsonb) TO nexus_svc;
DO $post$ DECLARE n int; BEGIN SELECT count(*) INTO n FROM pg_catalog.pg_proc p WHERE p.pronamespace = 'nexus'::pg_catalog.regnamespace AND p.proname = 'catalog_tag_set'; IF n <> 1 THEN RAISE EXCEPTION 'vectors-044-1: expected exactly 1 catalog_tag_set function, found %', n; END IF; SELECT count(*) INTO n FROM pg_catalog.pg_proc p WHERE p.pronamespace = 'nexus'::pg_catalog.regnamespace AND p.proname IN ('manifest_search_384', 'manifest_search_768', 'manifest_search_1024') AND p.prosrc LIKE '%nexus.catalog_tag_set(%'; IF n <> 3 THEN RAISE EXCEPTION 'vectors-044-1: expected the 3 manifest_search functions to call catalog_tag_set, found %', n; END IF; END $post$;

