CREATE OR REPLACE FUNCTION nexus.manifest_search_768( p_query nexus.vector(768), p_query_text text, p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_manifest_where jsonb, p_manifest_path text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_768 IS NOT NULL AND (p_chashes IS NULL OR c.chash = ANY(p_chashes)) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (p_query_text IS NULL OR c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id CROSS JOIN LATERAL ( SELECT nexus.catalog_source_format(d.content_type, d.file_path) AS fmt ) f CROSS JOIN LATERAL ( SELECT jsonb_build_object( 'section_title', CASE WHEN m.labels_written THEN to_jsonb(COALESCE(m.section_title, '')) ELSE COALESCE(NULLIF(c.metadata -> 'section_title', 'null'::jsonb), '""'::jsonb) END, 'section_type', CASE WHEN m.labels_written THEN to_jsonb(COALESCE(m.section_type, '')) ELSE COALESCE(NULLIF(c.metadata -> 'section_type', 'null'::jsonb), '""'::jsonb) END, 'page_number', CASE WHEN m.labels_written THEN COALESCE(to_jsonb(m.page_number), '""'::jsonb) ELSE COALESCE(NULLIF(c.metadata -> 'page_number', 'null'::jsonb), '""'::jsonb) END, 'title', CASE WHEN d.title ~ '\S' THEN to_jsonb(d.title) ELSE COALESCE(NULLIF(c.metadata -> 'title', 'null'::jsonb), '""'::jsonb) END, 'source_author', CASE WHEN COALESCE(d.author, '') ~ '\S' THEN to_jsonb(d.author) ELSE COALESCE(NULLIF(c.metadata -> 'source_author', 'null'::jsonb), '""'::jsonb) END, 'bib_doi', to_jsonb(d.bib_doi), 'bib_openalex_id', to_jsonb(d.bib_openalex_id), 'bib_semantic_scholar_id', to_jsonb(d.bib_semantic_scholar_id), 'content_type', to_jsonb(array_remove(ARRAY[ CASE WHEN d.content_type ~ '\S' THEN d.content_type END, f.fmt, CASE WHEN f.fmt IS NULL OR NOT (COALESCE(d.content_type, '') ~ '\S') THEN COALESCE(c.metadata ->> 'content_type', '') END ], NULL)) ) AS eff ) e WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash AND d.deleted_at IS NULL AND (p_manifest_where IS NULL OR e.eff @> p_manifest_where) AND (p_manifest_path IS NULL OR e.eff @@ p_manifest_path::jsonpath) ) ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.manifest_search_1024( p_query nexus.vector(1024), p_query_text text, p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_manifest_where jsonb, p_manifest_path text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_1024 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_1024 IS NOT NULL AND (p_chashes IS NULL OR c.chash = ANY(p_chashes)) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (p_query_text IS NULL OR c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id CROSS JOIN LATERAL ( SELECT nexus.catalog_source_format(d.content_type, d.file_path) AS fmt ) f CROSS JOIN LATERAL ( SELECT jsonb_build_object( 'section_title', CASE WHEN m.labels_written THEN to_jsonb(COALESCE(m.section_title, '')) ELSE COALESCE(NULLIF(c.metadata -> 'section_title', 'null'::jsonb), '""'::jsonb) END, 'section_type', CASE WHEN m.labels_written THEN to_jsonb(COALESCE(m.section_type, '')) ELSE COALESCE(NULLIF(c.metadata -> 'section_type', 'null'::jsonb), '""'::jsonb) END, 'page_number', CASE WHEN m.labels_written THEN COALESCE(to_jsonb(m.page_number), '""'::jsonb) ELSE COALESCE(NULLIF(c.metadata -> 'page_number', 'null'::jsonb), '""'::jsonb) END, 'title', CASE WHEN d.title ~ '\S' THEN to_jsonb(d.title) ELSE COALESCE(NULLIF(c.metadata -> 'title', 'null'::jsonb), '""'::jsonb) END, 'source_author', CASE WHEN COALESCE(d.author, '') ~ '\S' THEN to_jsonb(d.author) ELSE COALESCE(NULLIF(c.metadata -> 'source_author', 'null'::jsonb), '""'::jsonb) END, 'bib_doi', to_jsonb(d.bib_doi), 'bib_openalex_id', to_jsonb(d.bib_openalex_id), 'bib_semantic_scholar_id', to_jsonb(d.bib_semantic_scholar_id), 'content_type', to_jsonb(array_remove(ARRAY[ CASE WHEN d.content_type ~ '\S' THEN d.content_type END, f.fmt, CASE WHEN f.fmt IS NULL OR NOT (COALESCE(d.content_type, '') ~ '\S') THEN COALESCE(c.metadata ->> 'content_type', '') END ], NULL)) ) AS eff ) e WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash AND d.deleted_at IS NULL AND (p_manifest_where IS NULL OR e.eff @> p_manifest_where) AND (p_manifest_path IS NULL OR e.eff @@ p_manifest_path::jsonpath) ) ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
DROP FUNCTION IF EXISTS nexus.catalog_tag_set(jsonb);
